(window.__qhadithX=window.__qhadithX||{})[8]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 787","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-787","x":"The above mentioned tradition has been reported by ibn abbas through a different chain of narrators to the same effect. This version adds:\n\nThe apostle of Allah (ﷺ) died, but he did not mention to us that surah al baraah ins a part of al-anfal. Abu Dawood said: Al-sha’bl, Abu Malik, Qatadah, and Thabit b. ‘Umarah said: The prophet( may peace be upon him) did not write\"In the name of Allah, the compassionate, the merciful\" until Surah al-naml was revealed. This is the meaning of what they said. Further, this is a mursal traditional(omitting the name of the companion)","ar":"حَدَّثَنَا زِيَادُ بْنُ أَيُّوبَ، حَدَّثَنَا مَرْوَانُ، - يَعْنِي ابْنَ مُعَاوِيَةَ - أَخْبَرَنَا عَوْفٌ الأَعْرَابِيُّ، عَنْ يَزِيدَ الْفَارِسِيِّ، حَدَّثَنَا ابْنُ عَبَّاسٍ، بِمَعْنَاهُ قَالَ فِيهِ فَقُبِضَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلَمْ يُبَيِّنْ لَنَا أَنَّهَا مِنْهَا ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ الشَّعْبِيُّ وَأَبُو مَالِكٍ وَقَتَادَةُ وَثَابِتُ بْنُ عُمَارَةَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمْ يَكْتُبْ ‏{‏ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏}‏ حَتَّى نَزَلَتْ سُورَةُ النَّمْلِ هَذَا مَعْنَاهُ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2746","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2746","x":"Narrated Abdullah ibn Umar:\n\nThe Messenger of Allah (ﷺ) used to give to some of the detachments he sent out (something extra) for themselves in particular apart from the division made to the whole army. The fifth is necessary in all that.","ar":"حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ، قَالَ حَدَّثَنِي أَبِي، عَنْ جَدِّي، ح وَحَدَّثَنَا حَجَّاجُ بْنُ أَبِي يَعْقُوبَ، قَالَ حَدَّثَنِي حُجَيْنٌ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمٍ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَدْ كَانَ يُنَفِّلُ بَعْضَ مَنْ يَبْعَثُ مِنَ السَّرَايَا لأَنْفُسِهِمْ خَاصَّةً النَّفْلَ سِوَى قَسْمِ عَامَّةِ الْجَيْشِ وَالْخُمُسُ فِي ذَلِكَ وَاجِبٌ كُلُّهُ ‏.‏","v":[]},{"c":"Al-Adab Al-Mufrad","r":"Book 1, Hadith 24","u":"https://quranx.com/Hadith/Adab/English/Book-1/Hadith-24","x":"Sa'id ibn Abi Waqqas said:\n\n\"Four ayats were revealed about me. The first was when my mother swore she would neither eat nor drink until I left Muhammad, may Allah bless him and grant him peace. Allah Almighty revealed, 'But if they try to make you associate something with Me about which you have no knowledge, do not obey them. Keep company with them correctly and courteously in this world' (31:15) The second was when I took a sword that I admired and said, 'Messenger of Allah, give me this!' Then the ayat was revealed: 'They will ask you about booty.' (8:1) The third was when I was ill and the Messenger of Allah, may Allah bless him and grant him peace, came to me and I said, 'Messenger of Allah, I want to divide my property. Can I will away a half?' He said, 'No.' 'A third?' I asked. He was silent and so after that it was allowed to will away a third. The fourth was when I had been drinking wine with some of the Ansar. One of them hit my nose with the jawbone of a camel. I went to the Prophet, may Allah bless him and grant him peace, and Allah Almighty revealed the prohibition of wine.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، قَالَ‏:‏ حَدَّثَنَا إِسْرَائِيلُ، قَالَ‏:‏ حَدَّثَنَا سِمَاكٌ، عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ‏:‏ نَزَلَتْ فِيَّ أَرْبَعُ آيَاتٍ مِنْ كِتَابِ اللهِ تَعَالَى‏:‏ كَانَتْ أُمِّي حَلَفَتْ أَنْ لاَ تَأْكُلَ وَلاَ تَشْرَبَ حَتَّى أُفَارِقَ مُحَمَّدًا صلى الله عليه وسلم، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ‏:‏ ‏{‏وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلاَ تُطُعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا‏}‏‏.‏ وَالثَّانِيَةُ‏:‏ أَنِّي كُنْتُ أَخَذْتُ سَيْفًا أَعْجَبَنِي، فَقُلْتُ‏:‏ يَا رَسُولَ اللهِ، هَبْ لِي هَذَا، فَنَزَلَتْ‏:‏ ‏{‏يَسْأَلُونَكَ عَنِ الأَنْفَالِ‏}‏‏.‏ وَالثَّالِثَةُ‏:‏ أَنِّي مَرِضْتُ فَأَتَانِي رَسُولُ اللهِ صلى الله عليه وسلم، فَقُلْتُ‏:‏ يَا رَسُولَ اللهِ، إِنِّي أُرِيدُ أَنْ أَقْسِمَ مَالِي، أَفَأُوصِي بِالنِّصْفِ‏؟‏ فَقَالَ‏:‏ لاَ، فَقُلْتُ‏:‏ الثُّلُثُ‏؟‏ فَسَكَتَ، فَكَانَ الثُّلُثُ بَعْدَهُ جَائِزًا‏.‏ وَالرَّابِعَةُ‏:‏ إِنِّي شَرِبْتُ الْخَمْرَ مَعَ قَوْمٍ مِنَ الأَنْصَارِ، فَضَرَبَ رَجُلٌ مِنْهُمْ أَنْفِي بِلَحْيِ جَمَلٍ، فَأَتَيْتُ النَّبِيَّ صلى الله عليه وسلم فَأَنْزَلَ عَزَّ وَجَلَّ تَحْرِيمَ الْخَمْرِ‏.‏","v":[]},{"c":"Al-Adab Al-Mufrad","r":"Book 21, Hadith 392","u":"https://quranx.com/Hadith/Adab/English/Book-21/Hadith-392","x":"Regarding the ayat:\n\n\"Fear Allah and put things right between you,\" (8:1), Ibn 'Abbas said, \"This is an injunction from Allah to the believers to fear Allah and to put things right between them.\"","ar":"حَدَّثَنَا مُوسَى، قَالَ‏:‏ حَدَّثَنَا عَبَّادُ بْنُ الْعَوَّامِ، قَالَ‏:‏ أَخْبَرَنَا سُفْيَانُ بْنُ الْحُسَيْنِ، عَنِ الْحَكَمِ، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عَبَّاسٍ‏:‏ ‏{‏فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ‏}‏، قَالَ‏:‏ هَذَا تَحْرِيجٌ مِنَ اللهِ عَلَى الْمُؤْمِنِينَ أَنْ يَتَّقُوا اللَّهَ وَأَنْ يُصْلِحُوا ذَاتَ بَيْنِهِمْ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1748a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1748a","x":"A hadith has been narrated by Mus'ab b. Sa'd who heard it from his father as saying:\n\nMy father took a sword from Khums and brought it to the Prophet (ﷺ) and said: Grant it to me. He refused. At this Allah revealed (the Qur'anic verse):\" They ask thee concerning the spoils of war. Say: The spoils of war are for Allah and the Apostle\" (viii. 1).","ar":"وَحَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ سِمَاكٍ، عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، قَالَ أَخَذَ أَبِي مِنَ الْخُمْسِ سَيْفًا فَأَتَى بِهِ النَّبِيَّ صلى الله عليه وسلم فَقَالَ هَبْ لِي هَذَا ‏.‏ فَأَبَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَسْأَلُونَكَ عَنِ الأَنْفَالِ قُلِ الأَنْفَالُ لِلَّهِ وَالرَّسُولِ‏}‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 1748c","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-1748c","x":"Mus'ab b. Sa'd reported on the authority of his father that many verses of the Qur'an had been revealed in connection with him. His mother Umm Sa'd had taken oath that she would never talk with him until he abandoned his faith and she neither ate nor drank and said:\n\nAllah has commanded you to treat well your parents and I am your mother and I command you to do this. She passed three days in this state until she fainted because of extreme hunger and at that time her son whose name was Umara stood up and served her drink and she began to curse Sa'd that Allah, the Exalted and Glorions, revealed these verses of the Holy Qur'an:\" And We have enjoined upon a person goodness to his parents but if they contend with thee to associate (others) with Me of which you have no knowledge, then obey them not\" (xxix. 8) ; Treat thein with customary good in this world\" (xxxi. 15). He also reported that there fell to the lot of Allah's Messenger (ﷺ) huge spoils of war and there was one sword in them. I picked that up and came to Allah's Messenger (ﷺ) and said: Bestow this sword upon me (as my share in the spoils of war) and you know my state. Thereupon he said: Return it to the place from where you picked it up. I went back until I decided to throw it in a store but my soul repulsed me so I came back and asked him to give that sword to me. He said in a loud voice to return it to the place from where I had picked it up. It was on this occasion that this verse was revealed:\" They asked about the spoils of war\" (viii. 1). He further said: I once fell ill and sent a message to Allah's Apostle (ﷺ). He visited me and I said to him: Permit me to distribute (in charity) my property as much as I like. He did not agree. I said: (Permit me to distribute) half of it. He did not agree. I said: (Permit me to distribute) the third part, whereupon he kept quiet and it was after this (that the distribution of one's property in charity) to the extent of one-third was held valid. He further said: I came to a group of persons of the Ansir and Muhajirin and they said: Come, so that we may serve you wine, and it was before the use of wine had been prohibited. I went to them in a garden and there had been with them the roasted head of a camel and a small water-skin containing wine. I ate and drank along with them and there came under discussion the Ansr (Helpers) and Muhajirin (immigrants). I said: The immigrants are better than the Ansar, that a person picked up a portion of the head (of the camel and struck me with it that my nose was injured. I came to Allah's Messenger (ﷺ) and informed him of the situation that Aliah, the Exalted and Glorious, revealed verses pertaining to wine:\" Intoxicants and the games of chance and (sacrificing to) stones set up and (divining by) arrows are only an uncleanliness, the devil's work\" (v. 90).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَزُهَيْرُ بْنُ حَرْبٍ، قَالاَ حَدَّثَنَا الْحَسَنُ بْنُ مُوسَى، حَدَّثَنَا زُهَيْرٌ، حَدَّثَنَا سِمَاكُ بْنُ حَرْبٍ، حَدَّثَنِي مُصْعَبُ بْنُ سَعْدٍ، عَنْ أَبِيهِ، أَنَّهُ نَزَلَتْ فِيهِ آيَاتٌ مِنَ الْقُرْآنِ - قَالَ - حَلَفَتْ أُمُّ سَعْدٍ أَنْ لاَ تُكَلِّمَهُ أَبَدًا حَتَّى يَكْفُرَ بِدِينِهِ وَلاَ تَأْكُلَ وَلاَ تَشْرَبَ ‏.‏ قَالَتْ زَعَمْتَ أَنَّ اللَّهَ وَصَّاكَ بِوَالِدَيْكَ وَأَنَا أُمُّكَ وَأَنَا آمُرُكَ بِهَذَا ‏.‏ قَالَ مَكَثَتْ ثَلاَثًا حَتَّى غُشِيَ عَلَيْهَا مِنَ الْجَهْدِ فَقَامَ ابْنٌ لَهَا يُقَالُ لَهُ عُمَارَةُ فَسَقَاهَا فَجَعَلَتْ تَدْعُو عَلَى سَعْدٍ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِي الْقُرْآنِ هَذِهِ الآيَةَ ‏{‏ وَوَصَّيْنَا الإِنْسَانَ بِوَالِدَيْهِ حُسْنًا‏}‏ ‏{‏ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي‏}‏ وَفِيهَا ‏{‏ وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا‏}‏ قَالَ وَأَصَابَ رَسُولُ اللَّهِ صلى الله عليه وسلم غَنِيمَةً عَظِيمَةً فَإِذَا فِيهَا سَيْفٌ فَأَخَذْتُهُ فَأَتَيْتُ بِهِ الرَّسُولَ صلى الله عليه وسلم فَقُلْتُ نَفِّلْنِي هَذَا السَّيْفَ فَأَنَا مَنْ قَدْ عَلِمْتَ حَالَهُ ‏.‏ فَقَالَ ‏\"‏ رُدُّهُ مِنْ حَيْثُ أَخَذْتَهُ ‏\"‏ ‏.‏ فَانْطَلَقْتُ حَتَّى إِذَا أَرَدْتُ أَنْ أُلْقِيَهُ فِي الْقَبَضِ لاَمَتْنِي نَفْسِي فَرَجَعْتُ إِلَيْهِ فَقُلْتُ أَعْطِنِيهِ ‏.‏ قَالَ فَشَدَّ لِي صَوْتَهُ ‏\"‏ رُدُّهُ مِنْ حَيْثُ أَخَذْتَهُ ‏\"‏ ‏.‏ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَسْأَلُونَكَ عَنِ الأَنْفَالِ‏}‏ قَالَ وَمَرِضْتُ فَأَرْسَلْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَتَانِي فَقُلْتُ دَعْنِي أَقْسِمْ مَالِي حَيْثُ شِئْتُ ‏.‏ قَالَ فَأَبَى ‏.‏ قُلْتُ فَالنِّصْفَ ‏.‏ قَالَ فَأَبَى ‏.‏ قُلْتُ فَالثُّلُثَ ‏.‏ قَالَ فَسَكَتَ فَكَانَ بَعْدُ الثُّلُثُ جَائِزًا ‏.‏ قَالَ وَأَتَيْتُ عَلَى نَفَرٍ مِنَ الأَنْصَارِ وَالْمُهَاجِرِينَ فَقَالُوا تَعَالَ نُطْعِمْكَ وَنَسْقِيكَ خَمْرًا ‏.‏ وَذَلِكَ قَبْلَ أَنْ تُحَرَّمَ الْخَمْرُ - قَالَ - فَأَتَيْتُهُمْ فِي حَشٍّ - وَالْحَشُّ الْبُسْتَانُ - فَإِذَا رَأْسُ جَزُورٍ مَشْوِيٌّ عِنْدَهُمْ وَزِقٌّ مِنْ خَمْرٍ - قَالَ - فَأَكَلْتُ وَشَرِبْتُ مَعَهُمْ - قَالَ - فَذُكِرَتِ الأَنْصَارُ وَالْمُهَاجِرُونَ عِنْدَهُمْ فَقُلْتُ الْمُهَاجِرُونَ خَيْرٌ مِنَ الأَنْصَارِ - قَالَ - فَأَخَذَ رَجُلٌ أَحَدَ لَحْيَىِ الرَّأْسِ فَضَرَبَنِي بِهِ فَجَرَحَ بِأَنْفِي فَأَتَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيَّ - يَعْنِي نَفْسَهُ - شَأْنَ الْخَمْرِ ‏{‏ إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنْصَابُ وَالأَزْلاَمُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3079","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3079","x":"Narrated Mus'ab bin Sa'd:\n\nfrom his father who said: \"On the Day of Badr I brought a sword so I said: 'O Messenger of Allah! Indeed Allah has satisfied my breast (i.e. my desire) on the idolaters - or something like that - give me this sword.' So he said: 'This is not for me, nor is it for you.' I said: 'Perhaps he will give this to someone who did not go through some struggle I went through (fighting).' So the Messenger of Allah (ﷺ) came to me [and he said:] 'You asked me, but it was not up to me. But now it has occurred that it is up to me, so it is yours.'\" He said: \"So (the following) was revealed: They ask you about the spoils of war (8:1).\"","ar":"حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا أَبُو بَكْرِ بْنُ عَيَّاشٍ، عَنْ عَاصِمِ بْنِ بَهْدَلَةَ، عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، قَالَ لَمَّا كَانَ يَوْمُ بَدْرٍ جِئْتُ بِسَيْفٍ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ اللَّهَ قَدْ شَفَى صَدْرِي مِنَ الْمُشْرِكِينَ أَوْ نَحْوَ هَذَا هَبْ لِي هَذَا السَّيْفَ ‏.‏ فَقَالَ ‏\"‏ هَذَا لَيْسَ لِي وَلاَ لَكَ ‏\"‏ ‏.‏ فَقُلْتُ عَسَى أَنْ يُعْطَى هَذَا مَنْ لاَ يُبْلِي بَلاَئِي فَجَاءَنِي الرَّسُولُ فَقَالَ ‏\"‏ إِنَّكَ سَأَلْتَنِي وَلَيْسَ لِي وَقَدْ صَارَ لِي وَهُوَ لَكَ ‏\"‏ ‏.‏ قَالَ فَنَزَلَتْ ‏:‏ ‏(‏ يَسْأَلُونَكَ عَنِ الأَنْفَالِ ‏)‏ الآيَةَ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَاهُ سِمَاكُ بْنُ حَرْبٍ عَنْ مُصْعَبِ بْنِ سَعْدٍ أَيْضًا ‏.‏ وَفِي الْبَابِ عَنْ عُبَادَةَ بْنِ الصَّامِتِ ‏.‏","v":[]}],"9":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3081","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3081","x":"Narrated Ibn 'Abbas:\n\nfrom 'Umar bin Al-Khattab, who said: \"The Prophet (ﷺ) looked over the idolaters, and there were a thousand of them, while his Companions were three-hundred and ten and some odd number of men. So the Prophet of Allah (ﷺ) faced the Qiblah, stretched forth his hands and began beseeching his Lord: 'O Allah! Fulfill what You promised for me. [O Allah! Bring about what You promised for me] O Allah! If you destroy this band of adherents to Islam, you will not be worshiped upon the earth,' He continued beseeching his Lord with his hands stretched, facing the Qiblah until his Rida fell from his shoulders. Abu Bakr came to him, took his Rida and placed it back upon his shoulders, then embraced him from behind and said: 'O Prophet of Allah! You have sufficiently beseeched your Lord, indeed He shall fulfill what He promised you.' So Allah, Blessed and Most High, revealed: When you sought help of your Lord and He answered you (saying): 'I will help you with a thousand of the angels in succession (8:9).' [Abu 'Eisa said:] This Hadith is Hasan Sahih Gharib. We do not know of it as a Hadith of 'Umar, except through the narration of 'Ikrimah bin 'Ammar, from Abu Zumail, and Abu Zumail's name is Simãk Al-Hanafi. And this was on the Day of Badr.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عُمَرُ بْنُ يُونُسَ الْيَمَامِيُّ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ، حَدَّثَنَا أَبُو زُمَيْلٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَبَّاسٍ، حَدَّثَنَا عُمَرُ بْنُ الْخَطَّابِ، قَالَ نَظَرَ نَبِيُّ اللَّهِ صلى الله عليه وسلم إِلَى الْمُشْرِكِينَ وَهُمْ أَلْفٌ وَأَصْحَابُهُ ثَلاَثُمِائَةٍ وَبِضْعَةَ عَشَرَ رَجُلاً فَاسْتَقْبَلَ نَبِيُّ اللَّهِ صلى الله عليه وسلم الْقِبْلَةَ ثُمَّ مَدَّ يَدَيْهِ وَجَعَلَ يَهْتِفُ بِرَبِّهِ ‏\"‏ اللَّهُمَّ أَنْجِزْ لِي مَا وَعَدْتَنِي اللَّهُمَّ آتِنِي مَا وَعَدْتَنِي اللَّهُمَّ إِنْ تُهْلِكْ هَذِهِ الْعِصَابَةَ مِنْ أَهْلِ الإِسْلاَمِ لاَ تُعْبَدُ فِي الأَرْضِ ‏\"‏ ‏.‏ فَمَا زَالَ يَهْتِفُ بِرَبِّهِ مَادًّا يَدَيْهِ مُسْتَقْبِلَ الْقِبْلَةِ حَتَّى سَقَطَ رِدَاؤُهُ مِنْ مَنْكِبَيْهِ فَأَتَاهُ أَبُو بَكْرٍ فَأَخَذَ رِدَاءَهُ فَأَلْقَاهُ عَلَى مَنْكِبَيْهِ ثُمَّ الْتَزَمَهُ مِنْ وَرَائِهِ فَقَالَ يَا نَبِيَّ اللَّهِ كَفَاكَ مُنَاشَدَتُكَ رَبَّكَ فَإِنَّهُ سَيُنْجِزُ لَكَ مَا وَعَدَكَ فَأَنْزَلَ اللَّهُ ‏:‏ ‏(‏إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُمْ بِأَلْفٍ مِنَ الْمَلاَئِكَةِ مُرْدِفِينَ ‏)‏ فَأَمَدَّهُمُ اللَّهُ بِالْمَلاَئِكَةِ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ لاَ نَعْرِفُهُ مِنْ حَدِيثِ عُمَرَ إِلاَّ مِنْ حَدِيثِ عِكْرِمَةَ بْنِ عَمَّارٍ عَنْ أَبِي زُمَيْلٍ وَأَبُو زُمَيْلٍ اسْمُهُ سِمَاكٌ الْحَنَفِيُّ وَإِنَّمَا كَانَ هَذَا يَوْمَ بَدْرٍ ‏.‏","v":[]}],"16":[{"c":"Sunan Abu Dawud","r":"Hadith 2654","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2654","x":"Salamh (bin Al Akwa’) said \"I went on an expedition with the Apostle of Allaah(ﷺ) against Hawazin and while we were having a meal in the forenoon and most of our people were on foot and some of us were weak, a man came on a red Camel. He took out a rope from the lion of the Camel and tied his Camel with it and began to take meal with the people. When he saw the weak condition of their people and lack of mounts he went out in a hurry to his Camel, untied it made it kneel down and sat on it and went off galloping it. A man of the tribe of Aslam followed him on a brown she Camel which was best of those of the people. I hastened out and I found him while the head of the she Camel was near the paddock of the she Camel. I then went ahead till I reached near the paddock of the Camel. I then went ahead till I caught the Camel’s nose string. I made it kneel. When it placed its knee on the ground, I drew my sword and struck the man on his head and it fell down. I then brought the Camel leading it with (its equipment) on it. The Apostle of Allaah(ﷺ) came forward facing me and asked \"Who killed the man? They (the people) said \"Salamah bin Akwa’. He said \"he gets all his spoil.\" Harun said \"This is Hashim’s version.","ar":"حَدَّثَنَا هَارُونُ بْنُ عَبْدِ اللَّهِ، أَنَّ هَاشِمَ بْنَ الْقَاسِمِ، وَهِشَامًا، حَدَّثَاهُمْ قَالاَ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ، قَالَ حَدَّثَنِي إِيَاسُ بْنُ سَلَمَةَ، قَالَ حَدَّثَنِي أَبِي قَالَ، غَزَوْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم هَوَازِنَ - قَالَ - فَبَيْنَمَا نَحْنُ نَتَضَحَّى وَعَامَّتُنَا مُشَاةٌ وَفِينَا ضَعَفَةٌ إِذْ جَاءَ رَجُلٌ عَلَى جَمَلٍ أَحْمَرَ فَانْتَزَعَ طَلَقًا مِنْ حِقْوِ الْبَعِيرِ فَقَيَّدَ بِهِ جَمَلَهُ ثُمَّ جَاءَ يَتَغَدَّى مَعَ الْقَوْمِ فَلَمَّا رَأَى ضَعَفَتَهُمْ وَرِقَّةَ ظَهْرِهِمْ خَرَجَ يَعْدُو إِلَى جَمَلِهِ فَأَطْلَقَهُ ثُمَّ أَنَاخَهُ فَقَعَدَ عَلَيْهِ ثُمَّ خَرَجَ يَرْكُضُهُ وَاتَّبَعَهُ رَجُلٌ مِنْ أَسْلَمَ عَلَى نَاقَةٍ وَرْقَاءَ هِيَ أَمْثَلُ ظَهْرِ الْقَوْمِ - قَالَ - فَخَرَجْتُ أَعْدُو فَأَدْرَكْتُهُ وَرَأْسُ النَّاقَةِ عِنْدَ وَرِكِ الْجَمَلِ وَكُنْتُ عِنْدَ وَرِكِ النَّاقَةِ ثُمَّ تَقَدَّمْتُ حَتَّى كُنْتُ عِنْدَ وَرِكِ الْجَمَلِ ثُمَّ تَقَدَّمْتُ حَتَّى أَخَذْتُ بِخِطَامِ الْجَمَلِ فَأَنَخْتُهُ فَلَمَّا وَضَعَ رُكْبَتَهُ بِالأَرْضِ اخْتَرَطْتُ سَيْفِي فَأَضْرِبَ رَأْسَهُ فَنَدَرَ فَجِئْتُ بِرَاحِلَتِهِ وَمَا عَلَيْهَا أَقُودُهَا فَاسْتَقْبَلَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم فِي النَّاسِ مُقْبِلاً فَقَالَ ‏\"‏ مَنْ قَتَلَ الرَّجُلَ ‏\"‏ ‏.‏ فَقَالُوا سَلَمَةُ بْنُ الأَكْوَعِ ‏.‏ قَالَ ‏\"‏ لَهُ سَلَبُهُ أَجْمَعُ ‏\"‏ ‏.‏ قَالَ هَارُونُ هَذَا لَفْظُ هَاشِمٍ ‏.‏","v":[]},{"c":"Al-Adab Al-Mufrad","r":"Book 42, Hadith 972","u":"https://quranx.com/Hadith/Adab/English/Book-42/Hadith-972","x":"Ibn 'Umar said, \"We were on a raid and the people fled. We said, 'How can we meet the Prophet, may Allah bless him and grant him peace, when we have run away? It has been revealed, \"unless he is withdrawing to rejoin the fight\" (8:16).\" We said, 'We will not go to Madina and then no one will see us.' Then we said, 'Perhaps we should go.' The Prophet, may Allah bless him and grant him peace, came from the Fajr prayer and we said, 'We fled.' He said, 'You are those rejoining the fight.\"' We kissed his hand. He said, 'I am your group.*'\"","ar":"حَدَّثَنَا مُوسَى، قَالَ‏:‏ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ يَزِيدَ بْنِ أَبِي زِيَادٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنِ ابْنِ عُمَرَ قَالَ‏:‏ كُنَّا فِي غَزْوَةٍ، فَحَاصَ النَّاسُ حَيْصَةً، قُلْنَا‏:‏ كَيْفَ نَلْقَى النَّبِيَّ صلى الله عليه وسلم وَقَدْ فَرَرْنَا‏؟‏ فَنَزَلَتْ‏:‏ ‏{‏إِلاَّ مُتَحَرِّفًا لِقِتَالٍ‏}‏، فَقُلْنَا‏:‏ لاَ نَقْدِمُ الْمَدِينَةَ، فَلاَ يَرَانَا أَحَدٌ، فَقُلْنَا‏:‏ لَوْ قَدِمْنَا، فَخَرَجَ النَّبِيُّ صلى الله عليه وسلم مِنْ صَلاَةِ الْفَجْرِ، قُلْنَا‏:‏ نَحْنُ الْفَرَّارُونَ، قَالَ‏:‏ أَنْتُمُ الْعَكَّارُونَ، فَقَبَّلْنَا يَدَهُ، قَالَ‏:‏ أَنَا فِئَتُكُمْ‏.‏","v":[]}],"22":[{"c":"Sahih Bukhari","r":"Hadith 4646","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4646","x":"Narrated Ibn `Abbas:\n\nRegarding the Verse: \"Verily! The worst of beasts in the Sight of Allah are the deaf and the dumb---- those who understand not.\" (8.22) (The people referred to here) were some persons from the tribe of Bani `Abd-Addar.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ يُوسُفَ، حَدَّثَنَا وَرْقَاءُ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عَبَّاسٍ، ‏{‏إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللَّهِ الصُّمُّ الْبُكْمُ الَّذِينَ لاَ يَعْقِلُونَ‏}‏ قَالَ هُمْ نَفَرٌ مِنْ بَنِي عَبْدِ الدَّارِ‏.‏","v":[]}],"24":[{"c":"Sunan Abu Dawud","r":"Hadith 1458","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1458","x":"Abu Sa'id b. al-Mu'alla said that when he was praying the Prophet (ﷺ) passed by him and he called him. He said:\n\nI prayed ant then I came to him. He asked: What prevented you from answering me ? He replied: I was praying. He said: Has not Allah said: \"O you who believe, respond to Allah and the Apostle when he calls you to that which gives you life ? (8:24) Let me teach you the greatest surah from the Qur'an or in the Qur'an (the narrator Khalid doubted) before I leave the mosque. I said: (I shall memorize) your saying. He said: It is: \"Praise be to Allah, the Lord of the Universe\" which is the seven oft-repeated verses, and the mighty Qur'an.","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا خَالِدٌ، حَدَّثَنَا شُعْبَةُ، عَنْ خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ، قَالَ سَمِعْتُ حَفْصَ بْنَ عَاصِمٍ، يُحَدِّثُ عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى، أَنَّ النَّبِيَّ صلى الله عليه وسلم مَرَّ بِهِ وَهُوَ يُصَلِّي فَدَعَاهُ قَالَ فَصَلَّيْتُ ثُمَّ أَتَيْتُهُ قَالَ فَقَالَ ‏\"‏ مَا مَنَعَكَ أَنْ تُجِيبَنِي ‏\"‏ ‏.‏ قَالَ كُنْتُ أُصَلِّي ‏.‏ قَالَ ‏\"‏ أَلَمْ يَقُلِ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ‏}‏ لأُعَلِّمَنَّكَ أَعْظَمَ سُورَةٍ مِنَ الْقُرْآنِ أَوْ فِي الْقُرْآنِ ‏\"‏ ‏.‏ شَكَّ خَالِدٌ ‏\"‏ قَبْلَ أَنْ أَخْرُجَ مِنَ الْمَسْجِدِ ‏\"‏ ‏.‏ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ قَوْلَكَ ‏.‏ قَالَ ‏\"‏ ‏{‏ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}‏ وَهِيَ السَّبْعُ الْمَثَانِي الَّتِي أُوتِيتُ وَالْقُرْآنُ الْعَظِيمُ ‏\"‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4474","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4474","x":"Narrated Abu Sa`id bin Al-Mu'alla:\n\nWhile I was praying in the Mosque, Allah's Messenger (ﷺ) called me but I did not respond to him. Later I said, \"O Allah's Messenger (ﷺ)! I was praying.\" He said, \"Didn't Allah say'--\"Give your response to Allah (by obeying Him) and to His Apostle when he calls you.\" (8.24) He then said to me, \"I will teach you a Sura which is the greatest Sura in the Qur'an, before you leave the Mosque.\" Then he got hold of my hand, and when he intended to leave (the Mosque), I said to him, \"Didn't you say to me, 'I will teach you a Sura which is the greatest Sura in the Qur'an?' He said, \"Al-Hamdu-Li l-lah Rabbi-l-`alamin (i.e. Praise be to Allah, the Lord of the worlds) which is Al-Sab'a Al-Mathani (i.e. seven repeatedly recited Verses) and the Grand Qur'an which has been given to me.\"","ar":"حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ شُعْبَةَ، قَالَ حَدَّثَنِي خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ حَفْصِ بْنِ عَاصِمٍ، عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى، قَالَ كُنْتُ أُصَلِّي فِي الْمَسْجِدِ فَدَعَانِي رَسُولُ اللَّهِ صلى الله عليه وسلم فَلَمْ أُجِبْهُ، فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ أُصَلِّي‏.‏ فَقَالَ ‏\"‏ أَلَمْ يَقُلِ اللَّهُ ‏{‏اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ‏}‏ ثُمَّ قَالَ لِي لأُعَلِّمَنَّكَ سُورَةً هِيَ أَعْظَمُ السُّوَرِ فِي الْقُرْآنِ قَبْلَ أَنْ تَخْرُجَ مِنَ الْمَسْجِدِ ‏\"‏‏.‏ ثُمَّ أَخَذَ بِيَدِي، فَلَمَّا أَرَادَ أَنْ يَخْرُجَ قُلْتُ لَهُ أَلَمْ تَقُلْ ‏\"‏ لأُعَلِّمَنَّكَ سُورَةً هِيَ أَعْظَمُ سُورَةٍ فِي الْقُرْآنِ ‏\"‏‏.‏ قَالَ ‏\"‏ ‏{‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ‏}‏ هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُوتِيتُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4703","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4703","x":"Narrated Abu Sa`id Al-Mualla:\n\nWhile I was praying, the Prophet (ﷺ) passed by and called me, but I did not go to him till I had finished my prayer. When I went to him, he said, \"What prevented you from coming?\" I said, \"I was praying.\" He said, \"Didn't Allah say\" \"O you who believes Give your response to Allah (by obeying Him) and to His Apostle.\" (8.24) Then he added, \"Shall I tell you the most superior Sura in the Qur'an before I go out of the mosque?\" When the Prophet (ﷺ) intended to go out (of the Mosque), I reminded him and he said, \"That is: \"Al hamdu-li l-lahi Rabbil-`alamin (Surat-al-fatiha)' which is the seven oft repeated verses (Al-Mathani) and the Grand Qur'an which has been given to me.\"","ar":"حَدَّثَنِي مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا غُنْدَرٌ، حَدَّثَنَا شُعْبَةُ، عَنْ خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ حَفْصِ بْنِ عَاصِمٍ، عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى، قَالَ مَرَّ بِيَ النَّبِيُّ صلى الله عليه وسلم وَأَنَا أُصَلِّي فَدَعَانِي فَلَمْ آتِهِ حَتَّى صَلَّيْتُ ثُمَّ أَتَيْتُ فَقَالَ ‏\"‏ مَا مَنَعَكَ أَنْ تَأْتِيَ ‏\"‏‏.‏ فَقُلْتُ كُنْتُ أُصَلِّي‏.‏ فَقَالَ ‏\"‏ أَلَمْ يَقُلِ اللَّهُ ‏{‏يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ‏}‏ ثُمَّ قَالَ أَلاَ أُعَلِّمُكَ أَعْظَمَ سُورَةٍ فِي الْقُرْآنِ قَبْلَ أَنْ أَخْرُجَ مِنَ الْمَسْجِدِ ‏\"‏ فَذَهَبَ النَّبِيُّ صلى الله عليه وسلم لِيَخْرُجَ مِنَ الْمَسْجِدِ فَذَكَّرْتُهُ فَقَالَ ‏\"‏‏{‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ‏}‏ هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُوتِيتُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 5006","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-5006","x":"Narrated Abu Sa`id Al-Mu'alla:\n\nWhile I was praying, the Prophet (ﷺ) called me but I did not respond to his call. Later I said, \"O Allah's Apostle! I was praying.\" He said, \"Didn't Allah say: 'O you who believe! Give your response to Allah (by obeying Him) and to His Apostle when he calls you'?\" (8.24) He then said, \"Shall I not teach you the most superior Surah in the Qur'an?\" He said, '(It is), 'Praise be to Allah, the Lord of the worlds. ' (i.e., Surat Al-Fatiha) which consists of seven repeatedly recited Verses and the Magnificent Qur'an which was given to me.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا شُعْبَةُ، قَالَ حَدَّثَنِي خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ حَفْصِ بْنِ عَاصِمٍ، عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى، قَالَ كُنْتُ أُصَلِّي فَدَعَانِي النَّبِيُّ صلى الله عليه وسلم فَلَمْ أُجِبْهُ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ أُصَلِّي‏.‏ قَالَ ‏\"‏ أَلَمْ يَقُلِ اللَّهُ ‏{‏اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ‏}‏ ثُمَّ قَالَ أَلاَ أُعَلِّمُكَ أَعْظَمَ سُورَةٍ فِي الْقُرْآنِ قَبْلَ أَنْ تَخْرُجَ مِنَ الْمَسْجِدِ ‏\"‏‏.‏ فَأَخَذَ بِيَدِي فَلَمَّا أَرَدْنَا أَنْ نَخْرُجَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ قُلْتَ لأُعَلِّمَنَّكَ أَعْظَمَ سُورَةٍ مِنَ الْقُرْآنِ‏.‏ قَالَ ‏\"‏‏{‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ‏}‏ هِيَ السَّبْعُ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُوتِيتُهُ ‏\"‏‏.‏","v":[]}],"33":[{"c":"Sahih Bukhari","r":"Hadith 4648","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4648","x":"Narrated Anas bin Malik:\n\nAbu Jahl said, \"O Allah! If this (Qur'an) is indeed the Truth from You, then rain down on us a shower of stones from the sky or bring on us a painful torment.\" So Allah revealed:-- \"But Allah would not punish them while you were amongst them, nor He will punish them while they seek (Allah's) forgiveness...\" (8.33) And why Allah should not punish them while they turn away (men) from Al- Masjid-al-Haram (the Sacred Mosque of Mecca)...\" (8.33-34)","ar":"حَدَّثَنِي أَحْمَدُ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ ـ هُوَ ابْنُ كُرْدِيدٍ صَاحِبُ الزِّيَادِيِّ ـ سَمِعَ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ قَالَ أَبُو جَهْلٍ ‏{‏اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ‏}‏ فَنَزَلَتْ ‏{‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَنْ لاَ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4649","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4649","x":"Narrated Anas bin Malik:\n\nAbu Jahl said, \"O Allah! If this (Qur'an) is indeed the Truth from You), then rain down on us a shower of stones from the sky or bring on us a painful punishment.\" So there was revealed:-- 'But Allah would not punish them while you (Muhammad) were amongst them, nor will He punish them while they seek (Allah's) Forgiveness. And why Allah should not punish them while they stop (men) from Al-Masjid-al-Haram..' (8.33-34)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ النَّضْرِ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ، صَاحِبِ الزِّيَادِيِّ سَمِعَ أَنَسَ بْنَ مَالِكٍ، قَالَ قَالَ أَبُو جَهْلٍ ‏{‏اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ‏}‏ فَنَزَلَتْ ‏{‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَنْ لاَ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3082","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3082","x":"Narrated Abu Burdah bin Abi Musa:\n\nfrom his father, that the Messenger of Allah (ﷺ) said: \"Allah sent down two guarantees of safety for the benefit of my Ummah: And Allah would not punish them while you are among them, nor will He punish them while they seek forgiveness (8:33). So when I pass, I leave seeking forgiveness among them until the Day of Resurrection.\"","ar":"حَدَّثَنَا سُفْيَانُ بْنُ وَكِيعٍ، حَدَّثَنَا ابْنُ نُمَيْرٍ، عَنْ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ بْنِ مُهَاجِرٍ، عَنْ عَبَّادِ بْنِ يُوسُفَ، عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَنْزَلَ اللَّهُ عَلَىَّ أَمَانَيْنِ لأُمَّتِي ‏:‏ ‏(‏ وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ ‏)‏ ‏(‏ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ ‏)‏ إِذَا مَضَيْتُ تَرَكْتُ فِيهِمْ الاِسْتِغْفَارَ إِلَى يَوْمِ الْقِيَامَةِ ‏\"‏ ‏.‏ هَذَا حَدِيثٌ غَرِيبٌ ‏.‏ وَإِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ بْنِ مُهَاجِرٍ يُضَعَّفُ فِي الْحَدِيثِ ‏.‏","v":[]}],"34":[{"c":"Sahih Bukhari","r":"Hadith 4648","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4648","x":"Narrated Anas bin Malik:\n\nAbu Jahl said, \"O Allah! If this (Qur'an) is indeed the Truth from You, then rain down on us a shower of stones from the sky or bring on us a painful torment.\" So Allah revealed:-- \"But Allah would not punish them while you were amongst them, nor He will punish them while they seek (Allah's) forgiveness...\" (8.33) And why Allah should not punish them while they turn away (men) from Al- Masjid-al-Haram (the Sacred Mosque of Mecca)...\" (8.33-34)","ar":"حَدَّثَنِي أَحْمَدُ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ ـ هُوَ ابْنُ كُرْدِيدٍ صَاحِبُ الزِّيَادِيِّ ـ سَمِعَ أَنَسَ بْنَ مَالِكٍ ـ رضى الله عنه ـ قَالَ أَبُو جَهْلٍ ‏{‏اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ‏}‏ فَنَزَلَتْ ‏{‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَنْ لاَ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4649","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4649","x":"Narrated Anas bin Malik:\n\nAbu Jahl said, \"O Allah! If this (Qur'an) is indeed the Truth from You), then rain down on us a shower of stones from the sky or bring on us a painful punishment.\" So there was revealed:-- 'But Allah would not punish them while you (Muhammad) were amongst them, nor will He punish them while they seek (Allah's) Forgiveness. And why Allah should not punish them while they stop (men) from Al-Masjid-al-Haram..' (8.33-34)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ النَّضْرِ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ، صَاحِبِ الزِّيَادِيِّ سَمِعَ أَنَسَ بْنَ مَالِكٍ، قَالَ قَالَ أَبُو جَهْلٍ ‏{‏اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ‏}‏ فَنَزَلَتْ ‏{‏وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَنْ لاَ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2796","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2796","x":"Anas b. Malik reported that Abu Jahl said:\n\nO Allah, if he is true, then shower upon us the volley of stones from the sky or inflict upon us a grievous torment, and it was on this occasion that this verse was revealed:\" 'Allah would never torment them so long as you are amongst them. And Allah is not going to torment them as long as they seek forgiveness. And why is it that Allah should not torment them and they prevent people from coming to the sacred mosque....\" (viii. 34) to the end.","ar":"حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، حَدَّثَنَا أَبِي، حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ الْحَمِيدِ الزِّيَادِيِّ، أَنَّهُ سَمِعَ أَنَسَ بْنَ مَالِكٍ، يَقُولُ قَالَ أَبُو جَهْلٍ اللَّهُمَّ إِنْ كَانَ هَذَا هُوَ الْحَقَّ مِنْ عِنْدِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِنَ السَّمَاءِ أَوِ ائْتِنَا بِعَذَابٍ أَلِيمٍ ‏.‏ فَنَزَلَتْ ‏{‏ وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ وَمَا كَانَ اللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ * وَمَا لَهُمْ أَلاَّ يُعَذِّبَهُمُ اللَّهُ وَهُمْ يَصُدُّونَ عَنِ الْمَسْجِدِ الْحَرَامِ‏}‏ إِلَى آخِرِ الآيَةِ ‏.‏","v":[]}],"39":[{"c":"Sahih Bukhari","r":"Hadith 4650","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4650","x":"Narrated Ibn `Umar:\n\nThat a man came to him (while two groups of Muslims were fighting) and said, \"O Abu `Abdur Rahman! Don't you hear what Allah has mentioned in His Book: 'And if two groups of believers fight against each other...' (49.9) So what prevents you from fighting as Allah has mentioned in His Book?\"' Ibn `Umar said, \"O son of my brother! I would rather be blamed for not fighting because of this Verse than to be blamed because of another Verse where Allah says: 'And whoever kills a believer intentionally...\" (4.93) Then that man said, \"Allah says:-- 'And fight them until there is no more afflictions (worshipping other besides Allah) and the religion (i.e. worship) will be all for Allah (Alone)\" (8.39) Ibn `Umar said, \"We did this during the lifetime of Allah's Messenger (ﷺ) when the number of Muslims was small, and a man was put to trial because of his religion, the pagans would either kill or chain him; but when the Muslims increased (and Islam spread), there was no persecution.\" When that man saw that Ibn `Umar did not agree to his proposal, he said, \"What is your opinion regarding `Ali and `Uthman?\" Ibn `Umar said, \"What is my opinion regarding `Ali and `Uthman? As for `Uthman, Allah forgave him and you disliked to forgive him, and `Ali is the cousin and son-in-law of Allah's Messenger (ﷺ).\" Then he pointed out with his hand and said, \"And that is his daughter's (house) which you can see.\"","ar":"حَدَّثَنَا الْحَسَنُ بْنُ عَبْدِ الْعَزِيزِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَحْيَى، حَدَّثَنَا حَيْوَةُ، عَنْ بَكْرِ بْنِ عَمْرٍو، عَنْ بُكَيْرٍ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ أَنَّ رَجُلاً، جَاءَهُ فَقَالَ يَا أَبَا عَبْدِ الرَّحْمَنِ، أَلاَ تَسْمَعُ مَا ذَكَرَ اللَّهُ فِي كِتَابِهِ ‏{‏وَإِنْ طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا‏}‏ إِلَى آخِرِ الآيَةِ، فَمَا يَمْنَعُكَ أَنْ لاَ تُقَاتِلَ كَمَا ذَكَرَ اللَّهُ فِي كِتَابِهِ‏.‏ فَقَالَ يَا ابْنَ أَخِي أَغْتَرُّ بِهَذِهِ الآيَةِ وَلاَ أُقَاتِلُ أَحَبُّ إِلَىَّ مِنْ أَنْ أَغْتَرَّ بِهَذِهِ الآيَةِ الَّتِي يَقُولُ اللَّهُ تَعَالَى ‏{‏وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا‏}‏ إِلَى آخِرِهَا‏.‏ قَالَ فَإِنَّ اللَّهَ يَقُولُ ‏{‏وَقَاتِلُوهُمْ حَتَّى لاَ تَكُونَ فِتْنَةٌ‏}‏‏.‏ قَالَ ابْنُ عُمَرَ قَدْ فَعَلْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم إِذْ كَانَ الإِسْلاَمُ قَلِيلاً، فَكَانَ الرَّجُلُ يُفْتَنُ فِي دِينِهِ، إِمَّا يَقْتُلُوهُ وَإِمَّا يُوثِقُوهُ، حَتَّى كَثُرَ الإِسْلاَمُ، فَلَمْ تَكُنْ فِتْنَةٌ، فَلَمَّا رَأَى أَنَّهُ لاَ يُوَافِقُهُ فِيمَا يُرِيدُ قَالَ فَمَا قَوْلُكَ فِي عَلِيٍّ وَعُثْمَانَ‏.‏ قَالَ ابْنُ عُمَرَ مَا قَوْلِي فِي عَلِيٍّ وَعُثْمَانَ أَمَّا عُثْمَانُ فَكَانَ اللَّهُ قَدْ عَفَا عَنْهُ، فَكَرِهْتُمْ أَنْ يَعْفُوَ عَنْهُ، وَأَمَّا عَلِيٌّ فَابْنُ عَمِّ رَسُولِ اللَّهِ صلى الله عليه وسلم وَخَتَنُهُ‏.‏ وَأَشَارَ بِيَدِهِ وَهَذِهِ ابْنَتُهُ أَوْ بِنْتُهُ حَيْثُ تَرَوْنَ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 36, Hadith 3930","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-36/Hadith-3930","x":"It was narrated from Sumait bin Sumair, that ‘Imran bin Husain said:\n\n\"Nafi’ bin Azraq and his companions came and said: ‘You are doomed, O ‘Imran!’ He (‘Imran) said: ‘I am not doomed.’ They said: ‘Yes you are.’ I said: ‘Why am I doomed?’ They said: ‘Allah says: \"And fight them until there is no more Fitnah (disbelief and polytheism, i.e., worshipping others besides Allah), and the religion (worship) will be all for Allah Alone.\"[8:39] He said: ‘We fought them until they were defeated and the religion was all for Allah Alone. If you wish, I will tell you a Hadith that I heard from the Messenger of Allah (ﷺ).’ They said: ‘Did you (really) hear it from the Messenger of Allah (ﷺ)?’ He said: ‘Yes. I was with the Messenger of Allah (ﷺ) and he had sent an army of the Muslims to the idolaters. When they met them they fought them fiercely, and they (the idolaters) gave them their shoulders (i.e., turned and fled). A man among my kin attacked an idolator man with a spear, and when he was defeated he said: \"I bear witness that none has the right to be worshipped but Allah, I am a Muslim.\" But he stabbed him and killed him. He came to the Messenger of Allah (ﷺ) and said: \"O Messenger of Allah, I am doomed.\" He said \"What is it that you have done?\" one or two times. He told him what he had done and the Messenger of Allah (ﷺ) said to him: \"Why didn’t you cut open his belly and find out what was in his heart?\" He said: \"O Messenger of Allah, I wish I had cut open his belly and could have known what was in his heart.\" He said: \"You did not accept what he said, and you could not have known what was in his heart!\" The Messenger of Allah (ﷺ) remained silent concerning him (that man), and a short while later he died. We buried him, but the following morning he was on the surface of the earth. They said: \"Perhaps an enemy of his disinterred him.\" So we buried him (again) and told our slaves to stand guard. But the following morning he was on the surface of the earth again then we said: ‘Perhaps the slaves dozed off.’ So we buried him (again) and stood guard ourselves, but the following morning he was on the surface of the earth (again). So we threw him into one of these mountain passes.’\"","ar":"حَدَّثَنَا سُوَيْدُ بْنُ سَعِيدٍ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ عَاصِمٍ، عَنِ السُّمَيْطِ بْنِ السُّمَيْرِ، عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ، قَالَ أَتَى نَافِعُ بْنُ الأَزْرَقِ وَأَصْحَابُهُ فَقَالُوا هَلَكْتَ يَا عِمْرَانُ ‏.‏ قَالَ مَا هَلَكْتُ ‏.‏ قَالُوا بَلَى ‏.‏ قَالَ مَا الَّذِي أَهْلَكَنِي قَالُوا قَالَ اللَّهُ ‏{وَقَاتِلُوهُمْ حَتَّى لاَ تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ}‏ ‏.‏ قَالَ قَدْ قَاتَلْنَاهُمْ حَتَّى نَفَيْنَاهُمْ فَكَانَ الدِّينُ كُلُّهُ لِلَّهِ إِنْ شِئْتُمْ حَدَّثْتُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ‏.‏ قَالُوا وَأَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ‏.‏ قَالَ نَعَمْ شَهِدْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ وَقَدْ بَعَثَ جَيْشًا مِنَ الْمُسْلِمِينَ إِلَى الْمُشْرِكِينَ فَلَمَّا لَقُوهُمْ قَاتَلُوهُمْ قِتَالاً شَدِيدًا فَمَنَحُوهُمْ أَكْتَافَهُمْ فَحَمَلَ رَجُلٌ مِنْ لُحْمَتِي عَلَى رَجُلٍ مِنَ الْمُشْرِكِينَ بِالرُّمْحِ فَلَمَّا غَشِيَهُ قَالَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ إِنِّي مُسْلِمٌ فَطَعَنَهُ فَقَتَلَهُ فَأَتَى رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ فَقَالَ يَا رَسُولَ اللَّهِ هَلَكْتُ قَالَ ‏\"‏ وَمَا الَّذِي صَنَعْتَ ‏\"‏ ‏.‏ مَرَّةً أَوْ مَرَّتَيْنِ فَأَخْبَرَهُ بِالَّذِي صَنَعَ فَقَالَ لَهُ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ فَهَلاَّ شَقَقْتَ عَنْ بَطْنِهِ فَعَلِمْتَ مَا فِي قَلْبِهِ ‏\"‏ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ لَوْ شَقَقْتُ بَطْنَهُ أَكُنْتُ أَعْلَمُ مَا فِي قَلْبِهِ قَالَ ‏\"‏ فَلاَ أَنْتَ قَبِلْتَ مَا تَكَلَّمَ بِهِ وَلاَ أَنْتَ تَعْلَمُ مَا فِي قَلْبِهِ ‏\"‏ ‏.‏ قَالَ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فَلَمْ يَلْبَثْ إِلاَّ يَسِيرًا حَتَّى مَاتَ فَدَفَنَّاهُ فَأَصْبَحَ عَلَى ظَهْرِ الأَرْضِ فَقَالُوا لَعَلَّ عَدُوًّا نَبَشَهُ فَدَفَنَّاهُ ثُمَّ أَمَرْنَا غِلْمَانَنَا يَحْرُسُونَهُ فَأَصْبَحَ عَلَى ظَهْرِ الأَرْضِ فَقُلْنَا لَعَلَّ الْغِلْمَانَ نَعَسُوا فَدَفَنَّاهُ ثُمَّ حَرَسْنَاهُ بِأَنْفُسِنَا فَأَصْبَحَ عَلَى ظَهْرِ الأَرْضِ فَأَلْقَيْنَاهُ فِي بَعْضِ تِلْكَ الشِّعَابِ ‏.‏","v":[]},{"c":"Sunan Ibn Majah","r":"Volume 5, Book 36, Hadith 3930","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-36/Hadith-3930","x":"It was narrated from Sumait, from ‘Imran bin Husain who said:\n\n\"The Messenger of Allah (ﷺ) sent us on a campaign, and a Muslim man attacked an idolater man.\" And he mentioned the Hadith and added: \"And the earth cast him out. The Prophet (ﷺ) was told about that and he said: ‘The earth accepts those who are worse than him, but Allah wanted to show you how great is the sanctity of La ilaha illallah.’\"","ar":"حَدَّثَنَا إِسْمَاعِيلُ بْنُ حَفْصٍ الأُبُلِّيُّ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنْ عَاصِمٍ، عَنِ السُّمَيْطِ، عَنْ عِمْرَانَ بْنِ الْحُصَيْنِ، قَالَ بَعَثَنَا رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فِي سَرِيَّةٍ فَحَمَلَ رَجُلٌ مِنَ الْمُسْلِمِينَ عَلَى رَجُلٍ مِنَ الْمُشْرِكِينَ فَذَكَرَ الْحَدِيثَ وَزَادَ فِيهِ فَنَبَذَتْهُ الأَرْضُ فَأُخْبِرَ النَّبِيُّ ـ صلى الله عليه وسلم ـ وَقَالَ ‏\n\n\"‏ إِنَّ الأَرْضَ لَتَقْبَلُ مَنْ هُوَ أَشَرُّ مِنْهُ وَلَكِنَّ اللَّهَ أَحَبَّ أَنْ يُرِيَكُمْ تَعْظِيمَ حُرْمَةِ لاَ إِلَهَ إِلاَّ اللَّهُ ‏\"\n\n‏ ‏.‏","v":[]}],"41":[{"c":"Sahih Bukhari","r":"Hadith 335","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-335","x":"Narrated Jabir bin `Abdullah:\n\nThe Prophet (ﷺ) said, \"I have been given five things which were not given to any one else before me. -1. Allah made me victorious by terror, (by His frightening my enemies) for a distance of one month's journey. -2. The earth has been made for me (and for my followers) a place for praying and a thing to perform Tayammum, therefore anyone of my followers can pray wherever the time of a prayer is due. -3. The booty has been made Halal (lawful) for me yet it was not lawful for anyone else before me. -4. I have been given the right of intercession (on the Day of Resurrection). -5. Every Prophet used to be sent to his nation only but I have been sent to all mankind.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ سِنَانٍ، قَالَ حَدَّثَنَا هُشَيْمٌ، ح قَالَ وَحَدَّثَنِي سَعِيدُ بْنُ النَّضْرِ، قَالَ أَخْبَرَنَا هُشَيْمٌ، قَالَ أَخْبَرَنَا سَيَّارٌ، قَالَ حَدَّثَنَا يَزِيدُ ـ هُوَ ابْنُ صُهَيْبٍ الْفَقِيرُ ـ قَالَ أَخْبَرَنَا جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\n\n\"‏ أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الأَرْضُ مَسْجِدًا وَطَهُورًا، فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلاَةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِيَ الْمَغَانِمُ وَلَمْ تَحِلَّ لأَحَدٍ قَبْلِي، وَأُعْطِيتُ الشَّفَاعَةَ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ عَامَّةً ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 438","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-438","x":"Narrated Jabir bin `Abdullah:\n\nAllah's Messenger (ﷺ) said, \"I have been given five things which were not given to any amongst the Prophets before me. These are: -1. Allah made me victorious by terror (by His frightening my enemies) for a distance of one month's journey. -2. The earth has been made for me (and for my followers) a place for praying and a thing to perform Tayammum. Therefore my followers can pray wherever the time of a prayer is due. -3. The booty has been made Halal (lawful) for me (and was not made so for anyone else). -4. Every Prophet used to be sent to his nation exclusively but I have been sent to all mankind. -5. I have been given the right of intercession (on the Day of Resurrection.)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ سِنَانٍ، قَالَ حَدَّثَنَا هُشَيْمٌ، قَالَ حَدَّثَنَا سَيَّارٌ ـ هُوَ أَبُو الْحَكَمِ ـ قَالَ حَدَّثَنَا يَزِيدُ الْفَقِيرُ، قَالَ حَدَّثَنَا جَابِرُ بْنُ عَبْدِ اللَّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الأَنْبِيَاءِ قَبْلِي، نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الأَرْضُ مَسْجِدًا وَطَهُورًا، وَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلاَةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ كَافَّةً، وَأُعْطِيتُ الشَّفَاعَةَ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2254","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2254","x":"Narrated Muhammad bin Abi Al-Mujalid:\n\nAbu Burda and `Abdullah bin Shaddad sent me to `Abdur Rahman bin Abza and `Abdullah bin Abi `Aufa to ask them about the Salaf (Salam). They said, \"We used to get war booty while we were with Allah's Messenger (ﷺ) and when the peasants of Sham came to us we used to pay them in advance for wheat, barley, and oil to be delivered within a fixed period.\" I asked them, \"Did the peasants own standing crops or not?\" They replied, \"We never asked them about it.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ مُقَاتِلٍ، أَخْبَرَنَا عَبْدُ اللَّهِ، أَخْبَرَنَا سُفْيَانُ، عَنْ سُلَيْمَانَ الشَّيْبَانِيِّ، عَنْ مُحَمَّدِ بْنِ أَبِي مُجَالِدٍ، قَالَ أَرْسَلَنِي أَبُو بُرْدَةَ وَعَبْدُ اللَّهِ بْنُ شَدَّادٍ إِلَى عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى وَعَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى فَسَأَلْتُهُمَا عَنِ السَّلَفِ،‏.‏ فَقَالاَ كُنَّا نُصِيبُ الْمَغَانِمَ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَكَانَ يَأْتِينَا أَنْبَاطٌ مِنْ أَنْبَاطِ الشَّأْمِ فَنُسْلِفُهُمْ فِي الْحِنْطَةِ وَالشَّعِيرِ وَالزَّبِيبِ إِلَى أَجَلٍ مُسَمًّى‏.‏ قَالَ قُلْتُ أَكَانَ لَهُمْ زَرْعٌ، أَوْ لَمْ يَكُنْ لَهُمْ زَرْعٌ قَالاَ مَا كُنَّا نَسْأَلُهُمْ عَنْ ذَلِكَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2355","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2355","x":"Narrated Abu Huraira:\n\nAllah's Messenger (ﷺ) said, \"No bloodmoney will be charged if somebody dies in a mine or in a well or is killed by an animal; and if somebody finds a treasure in his land he has to give one-fifth of it to the Government.\"","ar":"حَدَّثَنَا مَحْمُودٌ، أَخْبَرَنَا عُبَيْدُ اللَّهِ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي حَصِينٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ الْمَعْدِنُ جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْعَجْمَاءُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ ‏\"\n\n‏‏.‏","v":[]},{"c":"Sunan an-Nasa'i","r":"Volume 5, Book 38, Hadith 4153","u":"https://quranx.com/Hadith/Nasai/DarusSalam/Volume-5/Book-38/Hadith-4153","x":"It was narrated that Malik bin Aws bin Al-Hadathan said:\n\n\"Al-Abbas and Ali came to 'Umar with a dispute. Al-Abbas said: 'Pass judgment between him and I.' the people said: 'Pass judgment between them.' 'Umar said: 'I will not pass judgment between them. They know that the Messenger of Allah said: We are not inherited from, what we leave behind is charity. He said: And (in this narration of it) Az-Zuhri said: 'It (the Khumus) was under the control of the Messenger of Allah, and he took provision for himself and for his family from it, and disposed to the rest of it as he disposed of other wealth (belonging to the Muslims). Then Abu Bakr took control of it, then I took control of it after Abu Bakr, and I did with it what he sued to do. Then these two came to me and asked me to give it to them so that they could dispose of it as the Messenger of Allah disposed of it, and as Abu Bakr disposed of it, and as I disposed of it. So I gave it to them and I took promises from them that they would take proper care of it. Then they came to me and this one said. Give me my share from my brothers son: and this one said: Give me my share from my wife. If they want me to give it to them on the condition that they would dispose of it in the same manner as the Messenger of Allah did, and as Abu Bakr did, and as I did, I would give it to them, but if they refuse, then they do not have to worry about it.' Then he said: 'And know that whatever of spoils of war that you may gain, verily, one-fifth of it is assigned to Allah, and to the Messenger, and to the near relatives (of the Messenger (Muhammad), (and also) the orphans, Al-Masakin (the poor) and the wayfarer' (Al-Anfal 8:41) this if for them. 'As-Sadaqat (here it means Zakah) are only for the Fuqara (poor), and Al-Masakin (the poor) and those employed to collect (the funds); and to attract the hearts of those who have been inclined (toward Islam); and to free the captives; and for those in debt; and for Allah's cause (I.e. for Mujahidun - those fighting in a holy battle)' - this is for them. 'And what Allah gave as booty (Fay') to His Messenger (Muhammad) from them - for this you made no expeditin with either cavalry or camels.' Az-Zuhri said: This applies exclusively to the Messenger of Allah and refers to an 'Arab village called Fadak, and so on. What Allah gave as booty (Fay') to His Messenger (Muhammad) from the people of the townships - it is for Allah, His Messenger (Muhammad), the kindred (of Messenger Muhammad), the orphans, Al-Masakin (the poor), and the wayfarer (And there is also a share in this booty) for the poor emigrants, who were expelled from their homes and their property And (it is also for) those who, before them, had homes (in Al-Madinah) and had adopted the Faith And those who came after them. These is no one left among the Muslims but he has some rights to this wealth, except for some of the slaved whom you own. If I live, if Allah wills, I will give every Muslim his right.\" Or he said: \"His share.\"","ar":"أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ، - يَعْنِي ابْنَ إِبْرَاهِيمَ - عَنْ أَيُّوبَ، عَنْ عِكْرِمَةَ بْنِ خَالِدٍ، عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ، قَالَ جَاءَ الْعَبَّاسُ وَعَلِيٌّ إِلَى عُمَرَ يَخْتَصِمَانِ فَقَالَ الْعَبَّاسُ اقْضِ بَيْنِي وَبَيْنَ هَذَا ‏.‏ فَقَالَ النَّاسُ افْصِلْ بَيْنَهُمَا ‏.‏ فَقَالَ عُمَرُ لاَ أَفْصِلُ بَيْنَهُمَا قَدْ عَلِمَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ ‏\"‏ ‏.‏ قَالَ فَقَالَ الزُّهْرِيُّ وَلِيَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم فَأَخَذَ مِنْهَا قُوتَ أَهْلِهِ وَجَعَلَ سَائِرَهُ سَبِيلَهُ سَبِيلَ الْمَالِ ثُمَّ وَلِيَهَا أَبُو بَكْرٍ بَعْدَهُ ثُمَّ وُلِّيتُهَا بَعْدَ أَبِي بَكْرٍ فَصَنَعْتُ فِيهَا الَّذِي كَانَ يَصْنَعُ ثُمَّ أَتَيَانِي فَسَأَلاَنِي أَنْ أَدْفَعَهَا إِلَيْهِمَا عَلَى أَنْ يَلِيَاهَا بِالَّذِي وَلِيَهَا بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَالَّذِي وَلِيَهَا بِهِ أَبُو بَكْرٍ وَالَّذِي وُلِّيتُهَا بِهِ فَدَفَعْتُهَا إِلَيْهِمَا وَأَخَذْتُ عَلَى ذَلِكَ عُهُودَهُمَا ثُمَّ أَتَيَانِي يَقُولُ هَذَا اقْسِمْ لِي بِنَصِيبِي مِنِ ابْنِ أَخِي ‏.‏ وُيَقُولُ هَذَا اقْسِمْ لِي بِنَصِيبِي مِنِ امْرَأَتِي ‏.‏ وَإِنْ شَاءَا أَنْ أَدْفَعَهَا إِلَيْهِمَا عَلَى أَنْ يَلِيَاهَا بِالَّذِي وَلِيَهَا بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم وَالَّذِي وَلِيَهَا بِهِ أَبُو بَكْرٍ وَالَّذِي وُلِّيتُهَا بِهِ دَفَعْتُهَا إِلَيْهِمَا وَإِنْ أَبَيَا كُفِيَا ذَلِكَ ثُمَّ قَالَ ‏{‏ وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ ‏}‏ هَذَا لِهَؤُلاَءِ ‏{‏ إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ ‏}‏ هَذِهِ لِهَؤُلاَءِ ‏{‏ وَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلاَ رِكَابٍ ‏}‏ قَالَ الزُّهْرِيُّ هَذِهِ لِرَسُولِ اللَّهِ صلى الله عليه وسلم خَاصَّةً قُرًى عَرَبِيَّةً فَدَكُ كَذَا وَكَذَا ‏{‏ مَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْ أَهْلِ الْقُرَى فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ ‏}‏ وَ ‏{‏ لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيَارِهِمْ وَأَمْوَالِهِمْ ‏}‏ ‏{‏ وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالإِيمَانَ مِنْ قَبْلِهِمْ ‏}‏ ‏{‏ وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ ‏}‏ فَاسْتَوْعَبَتْ هَذِهِ الآيَةُ النَّاسَ فَلَمْ يَبْقَ أَحَدٌ مِنَ الْمُسْلِمِينَ إِلاَّ لَهُ فِي هَذَا الْمَالِ حَقٌّ - أَوْ قَالَ حَظٌّ - إِلاَّ بَعْضَ مَنْ تَمْلِكُونَ مِنْ أَرِقَّائِكُمْ وَلَئِنْ عِشْتُ إِنْ شَاءَ اللَّهُ لَيَأْتِيَنَّ عَلَى كُلِّ مُسْلِمٍ حَقُّهُ أَوْ قَالَ حَظُّهُ ‏.‏","v":[]}],"60":[{"c":"Sunan Ibn Majah","r":"Volume 4, Book 24, Hadith 2813","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-4/Book-24/Hadith-2813","x":"It was narrated that ‘Uqbah bin ‘Amir Al-Juhani said:\n\n\"I heard the Messenger of Allah (ﷺ) reciting on the pulpit: ‘And make ready against them all you can of power.’[8:60] (And saying that) three times – ‘Power means shooting.\"","ar":"حَدَّثَنَا يُونُسُ بْنُ عَبْدِ الأَعْلَى، أَنْبَأَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنِي عَمْرُو بْنُ الْحَارِثِ، عَنْ أَبِي عَلِيٍّ الْهَمْدَانِيِّ، أَنَّهُ سَمِعَ عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ، يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْرَأُ عَلَى الْمِنْبَرِ ‏\"‏ ‏{وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ}‏ أَلاَ وَإِنَّ الْقُوَّةَ الرَّمْىُ ‏\"‏ ثَلاَثَ مَرَّاتٍ ‏.‏","v":[]},{"c":"Muwatta Malik","r":"Book 21, Hadith 982","u":"https://quranx.com/Hadith/Malik/In-Book/Book-21/Hadith-982","x":"Yahya related to me that Malik said that he had heard that Umar ibn Abd al-Aziz used to say, \"The man on horse-back has two shares, and the man on foot has one.\" Malik added, \"I continue to hear the same.\" Malik, when asked whether a man who was present with several horses took a share for all of them, said, \"I have never heard that. I think that there is only a share for the horse on which he fought.\" Malik said, \"I think that foreign horses and half-breeds are considered as horses because Allah, the Blessed, the Exalted, said in His Book, 'All horses, and mules, and asses, for you to ride, and as an adornment.' (Sura16 ayat 8). He said, the Mighty, the Majestic, 'Make ready for them whatever force and strings of horses you can, to terrify thereby the enemy of Allah and your enemy.' (Sura 8 ayat 60). I think that foreign breeds and half-breeds are considered as horses if the governor accepts them.\" Said ibn al-Musayyab was asked about working horses, and whether there was zakat on them. He said, \"Is there any zakat on horses.?\"","ar":"حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ قَالَ بَلَغَنِي أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، كَانَ يَقُولُ لِلْفَرَسِ سَهْمَانِ وَلِلرَّجُلِ سَهْمٌ ‏.‏ قَالَ مَالِكٌ وَلَمْ أَزَلْ أَسْمَعُ ذَلِكَ ‏.‏ وَسُئِلَ مَالِكٌ عَنْ رَجُلٍ يَحْضُرُ بِأَفْرَاسٍ كَثِيرَةٍ فَهَلْ يُقْسَمُ لَهَا كُلِّهَا فَقَالَ لَمْ أَسْمَعْ بِذَلِكَ وَلاَ أَرَى أَنْ يُقْسَمَ إِلاَّ لِفَرَسٍ وَاحِدٍ الَّذِي يُقَاتِلُ عَلَيْهِ ‏.‏ قَالَ مَالِكٌ لاَ أَرَى الْبَرَاذِينَ وَالْهُجُنَ إِلاَّ مِنَ الْخَيْلِ لأَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ فِي كِتَابِهِ ‏{‏وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً‏}‏ وَقَالَ عَزَّ وَجَلَّ ‏{‏وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ‏}‏ فَأَنَا أَرَى الْبَرَاذِينَ وَالْهُجُنَ مِنَ الْخَيْلِ إِذَا أَجَازَهَا الْوَالِي وَقَدْ قَالَ سَعِيدُ بْنُ الْمُسَيَّبِ وَسُئِلَ عَنِ الْبَرَاذِينَ هَلْ فِيهَا مِنْ صَدَقَةٍ فَقَالَ وَهَلْ فِي الْخَيْلِ مِنْ صَدَقَةٍ","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3083","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3083","x":"Narrated 'Uqbah bin 'Amir:\n\nthat the Messenger of Allah (ﷺ) recited this Ayah upon the Minbar: And make ready against them all you can of power (8:60). He said: \"Verily! Power is shooting\" - three times - \"Verily! Allah will open the earth for you and suffice you with supplies, so let none of you forsake practicing with his arrows.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا وَكِيعٌ، عَنْ أُسَامَةَ بْنِ زَيْدٍ، عَنْ صَالِحِ بْنِ كَيْسَانَ، عَنْ رَجُلٍ، لَمْ يُسَمِّهِ عَنْ عُقْبَةَ بْنِ عَامِرٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَرَأَ هَذِهِ الآيَةَ عَلَى الْمِنْبَرِ ‏:‏ ‏(‏ وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ ‏)‏ قَالَ ‏\"‏ أَلاَ إِنَّ الْقُوَّةَ الرَّمْىُ ثَلاَثَ مَرَّاتٍ أَلاَ إِنَّ اللَّهَ سَيَفْتَحُ لَكُمُ الأَرْضَ وَسَتُكْفَوْنَ الْمُؤْنَةَ فَلاَ يَعْجِزَنَّ أَحَدُكُمْ أَنْ يَلْهُوَ بِأَسْهُمِهِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى بَعْضُهُمْ هَذَا الْحَدِيثَ عَنْ أُسَامَةَ بْنِ زَيْدٍ عَنْ صَالِحِ بْنِ كَيْسَانَ عَنْ عُقْبَةَ بْنِ عَامِرٍ رَوَاهُ أَبُو أُسَامَةَ وَغَيْرُ وَاحِدٍ وَحَدِيثُ وَكِيعٍ أَصَحُّ ‏.‏ وَصَالِحُ بْنُ كَيْسَانَ لَمْ يُدْرِكْ عُقْبَةَ بْنَ عَامِرٍ وَقَدْ أَدْرَكَ ابْنَ عُمَرَ ‏.‏","v":[]}],"65":[{"c":"Sunan Abu Dawud","r":"Hadith 2652","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2652","x":"Narrated Furat ibn Hayyan:\n\nThe Messenger of Allah (ﷺ) commanded to kill him: he was a spy of AbuSufyan and an ally of a man of the Ansar. He passed a circle of the Ansar and said: I am a Muslim. A man from the Ansar said, Messenger of Allah, he is saying that he is a Muslim. The Messenger of Allah (ﷺ) said: There are people among you in whose faith we trust. Furat ibn Hayyan is one of them.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنِي مُحَمَّدُ بْنُ مُحَبَّبٍ أَبُو هَمَّامٍ الدَّلاَّلُ، حَدَّثَنَا سُفْيَانُ بْنُ سَعِيدٍ، عَنْ أَبِي إِسْحَاقَ، عَنْ حَارِثَةَ بْنِ مُضَرِّبٍ، عَنْ فُرَاتِ بْنِ حَيَّانَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَمَرَ بِقَتْلِهِ وَكَانَ عَيْنًا لأَبِي سُفْيَانَ وَكَانَ حَلِيفًا لِرَجُلٍ مِنَ الأَنْصَارِ فَمَرَّ بِحَلْقَةٍ مِنَ الأَنْصَارِ فَقَالَ إِنِّي مُسْلِمٌ ‏.‏ فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ يَا رَسُولَ اللَّهِ إِنَّهُ يَقُولُ إِنِّي مُسْلِمٌ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ إِنَّ مِنْكُمْ رِجَالاً نَكِلُهُمْ إِلَى إِيمَانِهِمْ مِنْهُمْ فُرَاتُ بْنُ حَيَّانَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4652","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4652","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:-- \"If there are twenty steadfast amongst you, they will overcome two hundred.\" (8.65) was revealed, then it became obligatory for the Muslims that one (Muslim) should not flee from ten (non-Muslims). Sufyan (the sub-narrator) once said, \"Twenty (Muslims) should not flee before two hundred (non Muslims).\" Then there was revealed: 'But now Allah has lightened your (task)..' (8.66) So it became obligatory that one-hundred (Muslims) should not flee before two hundred (nonmuslims). (Once Sufyan said extra, \"The Verse: 'Urge the believers to the fight. If there are twenty steadfast amongst you (Muslims)..' was revealed.) Sufyan said, \"Ibn Shabrama said, \"I see that this order is applicable to the obligation of enjoining good and forbidding evil.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ لَمَّا نَزَلَتْ ‏{‏إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ‏}‏ فَكُتِبَ عَلَيْهِمْ أَنْ لاَ يَفِرَّ وَاحِدٌ مِنْ عَشَرَةٍ ـ فَقَالَ سُفْيَانُ غَيْرَ مَرَّةٍ أَنْ لاَ يَفِرَّ عِشْرُونَ مِنْ مِائَتَيْنِ ـ ثُمَّ نَزَلَتِ ‏{‏الآنَ خَفَّفَ اللَّهُ عَنْكُمُ‏}‏ الآيَةَ، فَكَتَبَ أَنْ لاَ يَفِرَّ مِائَةٌ مِنْ مِائَتَيْنِ ـ زَادَ سُفْيَانُ مَرَّةً ـ نَزَلَتْ ‏{‏حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتَالِ إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ‏}‏‏.‏ قَالَ سُفْيَانُ وَقَالَ ابْنُ شُبْرُمَةَ وَأُرَى الأَمْرَ بِالْمَعْرُوفِ وَالنَّهْىَ عَنِ الْمُنْكَرِ مِثْلَ هَذَا‏.‏","v":[]}],"66":[{"c":"Sunan Abu Dawud","r":"Hadith 2652","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2652","x":"Narrated Furat ibn Hayyan:\n\nThe Messenger of Allah (ﷺ) commanded to kill him: he was a spy of AbuSufyan and an ally of a man of the Ansar. He passed a circle of the Ansar and said: I am a Muslim. A man from the Ansar said, Messenger of Allah, he is saying that he is a Muslim. The Messenger of Allah (ﷺ) said: There are people among you in whose faith we trust. Furat ibn Hayyan is one of them.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنِي مُحَمَّدُ بْنُ مُحَبَّبٍ أَبُو هَمَّامٍ الدَّلاَّلُ، حَدَّثَنَا سُفْيَانُ بْنُ سَعِيدٍ، عَنْ أَبِي إِسْحَاقَ، عَنْ حَارِثَةَ بْنِ مُضَرِّبٍ، عَنْ فُرَاتِ بْنِ حَيَّانَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَمَرَ بِقَتْلِهِ وَكَانَ عَيْنًا لأَبِي سُفْيَانَ وَكَانَ حَلِيفًا لِرَجُلٍ مِنَ الأَنْصَارِ فَمَرَّ بِحَلْقَةٍ مِنَ الأَنْصَارِ فَقَالَ إِنِّي مُسْلِمٌ ‏.‏ فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ يَا رَسُولَ اللَّهِ إِنَّهُ يَقُولُ إِنِّي مُسْلِمٌ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\n\n\"‏ إِنَّ مِنْكُمْ رِجَالاً نَكِلُهُمْ إِلَى إِيمَانِهِمْ مِنْهُمْ فُرَاتُ بْنُ حَيَّانَ ‏\"\n\n‏ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4652","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4652","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:-- \"If there are twenty steadfast amongst you, they will overcome two hundred.\" (8.65) was revealed, then it became obligatory for the Muslims that one (Muslim) should not flee from ten (non-Muslims). Sufyan (the sub-narrator) once said, \"Twenty (Muslims) should not flee before two hundred (non Muslims).\" Then there was revealed: 'But now Allah has lightened your (task)..' (8.66) So it became obligatory that one-hundred (Muslims) should not flee before two hundred (nonmuslims). (Once Sufyan said extra, \"The Verse: 'Urge the believers to the fight. If there are twenty steadfast amongst you (Muslims)..' was revealed.) Sufyan said, \"Ibn Shabrama said, \"I see that this order is applicable to the obligation of enjoining good and forbidding evil.\"","ar":"حَدَّثَنَا عَلِيُّ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا سُفْيَانُ، عَنْ عَمْرٍو، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ لَمَّا نَزَلَتْ ‏{‏إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ‏}‏ فَكُتِبَ عَلَيْهِمْ أَنْ لاَ يَفِرَّ وَاحِدٌ مِنْ عَشَرَةٍ ـ فَقَالَ سُفْيَانُ غَيْرَ مَرَّةٍ أَنْ لاَ يَفِرَّ عِشْرُونَ مِنْ مِائَتَيْنِ ـ ثُمَّ نَزَلَتِ ‏{‏الآنَ خَفَّفَ اللَّهُ عَنْكُمُ‏}‏ الآيَةَ، فَكَتَبَ أَنْ لاَ يَفِرَّ مِائَةٌ مِنْ مِائَتَيْنِ ـ زَادَ سُفْيَانُ مَرَّةً ـ نَزَلَتْ ‏{‏حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتَالِ إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ‏}‏‏.‏ قَالَ سُفْيَانُ وَقَالَ ابْنُ شُبْرُمَةَ وَأُرَى الأَمْرَ بِالْمَعْرُوفِ وَالنَّهْىَ عَنِ الْمُنْكَرِ مِثْلَ هَذَا‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4653","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4653","x":"Narrated Ibn `Abbas:\n\nWhen the Verse:--'If there are twenty steadfast amongst you (Muslims), they will overcome twohundred (non-Muslims).' was revealed, it became hard on the Muslims when it became compulsory that one Muslim ought not to flee (in war) before ten (non-Muslims). So (Allah) lightened the order by revealing: '(But) now Allah has lightened your (task) for He knows that there is weakness in you. So if there are of you one-hundred steadfast, they will overcome (two-hundred (non-Muslims).' (8.66) So when Allah reduced the number of enemies which Muslims should withstand, their patience and perseverance against the enemy decreased as much as their task was lightened for them.","ar":"حَدَّثَنَا يَحْيَى بْنُ عَبْدِ اللَّهِ السُّلَمِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ، أَخْبَرَنَا جَرِيرُ بْنُ حَازِمٍ، قَالَ أَخْبَرَنِي الزُّبَيْرُ بْنُ خِرِّيتٍ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ لَمَّا نَزَلَتْ ‏{‏إِنْ يَكُنْ مِنْكُمْ عِشْرُونَ صَابِرُونَ يَغْلِبُوا مِائَتَيْنِ‏}‏ شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ حِينَ فُرِضَ عَلَيْهِمْ أَنْ لاَ يَفِرَّ وَاحِدٌ مِنْ عَشَرَةٍ، فَجَاءَ التَّخْفِيفُ فَقَالَ رالآنَ خَفَّفَ اللَّهُ عَنْكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضُعْفًا فَإِنْ يَكُنْ مِنْكُمْ مِائَةٌ صَابِرَةٌ يَغْلِبُوا مِائَتَيْنِ‏}‏‏.‏ قَالَ فَلَمَّا خَفَّفَ اللَّهُ عَنْهُمْ مِنَ الْعِدَّةِ نَقَصَ مِنَ الصَّبْرِ بِقَدْرِ مَا خُفِّفَ عَنْهُمْ‏.‏","v":[]}],"67":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3084","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3084","x":"Narrated 'Amr bin Murrah:\n\nthat Abu 'Ubaidah bin 'Abdullah narrated from 'Abdullah bin Mas'ud who said: \"On the Day of Badr, when the captives were brought, the Messenger of Allah (ﷺ) said 'What do you say about these captives?' So he mentioned the story. And the Messenger of Allah (ﷺ) said 'Not one of them should be released without a ransom, or a blow to the neck.'\" So 'Abdullah bin Mas'ud said: \"O Messenger of Allah! With the exception of Suhail bin Baidam for indeed I heard him mentioning Islam.\" He said: \"So the Messenger of Allah (ﷺ) was silent.\" He said: \"I have not seen a day upon which I was more fearful of stones falling from the heavens upon my head that the day.\" [He said:] \"Until the Messenger of Allah (ﷺ) said: 'Except for Suhail bin Al-Baida.'\" He said: \"And the Qur'an was revealed in accordance with the view of 'Umar. 'It is not (fitting) for a Prophet that he should have prisoners of war until he has fought (his enemies thoroughly) in the land...' until the end of the Ayat.\"","ar":"حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ عَمْرِو بْنِ مُرَّةَ، عَنْ أَبِي عُبَيْدَةَ بْنِ عَبْدِ اللَّهِ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ لَمَّا كَانَ يَوْمُ بَدْرٍ وَجِيءَ بِالأُسَارَى قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا تَقُولُونَ فِي هَؤُلاَءِ الأُسَارَى ‏\"‏ ‏.‏ فَذَكَرَ فِي الْحَدِيثِ قِصَّةً فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ يَنْفَلِتَنَّ مِنْهُمْ أَحَدٌ إِلاَّ بِفِدَاءٍ أَوْ ضَرْبِ عُنُقٍ ‏\"‏ ‏.‏ قَالَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ فَقُلْتُ يَا رَسُولَ اللَّهِ إِلاَّ سُهَيْلَ بْنَ بَيْضَاءَ فَإِنِّي قَدْ سَمِعْتُهُ يَذْكُرُ الإِسْلاَمَ ‏.‏ قَالَ فَسَكَتَ رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَ فَمَا رَأَيْتُنِي فِي يَوْمٍ أَخْوَفَ أَنْ تَقَعَ عَلَىَّ حِجَارَةٌ مِنَ السَّمَاءِ مِنِّي فِي ذَلِكَ الْيَوْمِ قَالَ حَتَّى قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِلاَّ سُهَيْلَ ابْنَ بَيْضَاءَ ‏\"‏ ‏.‏ قَالَ وَنَزَلَ الْقُرْآنُ بِقَوْلِ عُمَرَ ‏:‏ ‏(‏ مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى يُثْخِنَ فِي الأَرْضِ ‏)‏ إِلَى آخِرِ الآيَاتِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَأَبُو عُبَيْدَةَ بْنُ عَبْدِ اللَّهِ لَمْ يَسْمَعْ مِنْ أَبِيهِ ‏.‏","v":[]}],"68":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3085","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3085","x":"Narrated Abu Hurairah:\n\nthat the Prophet (ﷺ) said: \"None of the black heads (meaning the Children of Adam since (most of) their heads are black) before you partook of spoils of war, but fire from the heavens would be sent down upon them, consuming them.\" Sulaiman (one of the narrators) said \"No one says this except for Abu Hurairah now. \"So on the day of Badr when they had the spoils of war before it was made lawful for them, Allah [Most High] revealed: Were it not a previous ordainment from Allah, a severe torment would have touched you for what you took.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنِي مُعَاوِيَةُ بْنُ عَمْرٍو، عَنْ زَائِدَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ لَمْ تَحِلَّ الْغَنَائِمُ لأَحَدٍ سُودِ الرُّءُوسِ مِنْ قَبْلِكُمْ كَانَتْ تَنْزِلُ نَارٌ مِنَ السَّمَاءِ فَتَأْكُلُهَا ‏\"‏ ‏.‏ قَالَ سُلَيْمَانُ الأَعْمَشُ فَمَنْ يَقُولُ هَذَا إِلاَّ أَبُو هُرَيْرَةَ الآنَ فَلَمَّا كَانَ يَوْمُ بَدْرٍ وَقَعُوا فِي الْغَنَائِمِ قَبْلَ أَنْ تَحِلَّ لَهُمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏:‏ ‏(‏لَوْلاَ كِتَابٌ مِنَ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيمٌ ‏)‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ مِنْ حَدِيثِ الأَعْمَشِ ‏.‏","v":[]}],"72":[{"c":"Sunan Abu Dawud","r":"Hadith 2930","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2930","x":"Narrated Abu Musa:\n\nI went along with two men to see the Prophet (ﷺ). One of them recited tashahhud and said: We have come to you so that you may employ us for your work. The other also said the same thing. He (the Prophet) replied: The most faithless of you in our eyes is the one who asked for it (responsible post). Abu Musa then apologized to the Prophet (ﷺ) and said: I did not know why they came to you. He did not employ them for anything until he died.","ar":"حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، حَدَّثَنَا خَالِدٌ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنْ أَخِيهِ، عَنْ بِشْرِ بْنِ قُرَّةَ الْكَلْبِيِّ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى، قَالَ انْطَلَقْتُ مَعَ رَجُلَيْنِ إِلَى النَّبِيِّ صلى الله عليه وسلم فَتَشَهَّدَ أَحَدُهُمَا ثُمَّ قَالَ جِئْنَا لِتَسْتَعِينَ بِنَا عَلَى عَمَلِكَ ‏.‏ وَقَالَ الآخَرُ مِثْلَ قَوْلِ صَاحِبِهِ ‏.‏ فَقَالَ ‏\n\n\"‏ إِنَّ أَخْوَنَكُمْ عِنْدَنَا مَنْ طَلَبَهُ ‏\"\n\n‏ ‏.‏ فَاعْتَذَرَ أَبُو مُوسَى إِلَى النَّبِيِّ صلى الله عليه وسلم وَقَالَ لَمْ أَعْلَمْ لِمَا جَاءَا لَهُ ‏.‏ فَلَمْ يَسْتَعِنْ بِهِمَا عَلَى شَىْءٍ حَتَّى مَاتَ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1588","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1588","x":"Narrated 'Usama bin Zaid:\n\nI asked, \"O Allah's Messenger (ﷺ)! Where will you stay in Mecca? Will you stay in your house in Mecca?\" He replied, \"Has `Aqil left any property or house?\" `Aqil along with Talib had inherited the property of Abu Talib. Jafar and `Ali did not inherit anything as they were Muslims and the other two were non-believers. `Umar bin Al-Khattab used to say, \"A believer cannot inherit (anything from an) infidel.\" Ibn Shihab, (a sub-narrator) said, \"They (`Umar and others) derived the above verdict from Allah's Statement: \"Verily! those who believed and Emigrated and strove with their life And property in Allah's Cause, And those who helped (the emigrants) And gave them their places to live in, These are (all) allies to one another.\" (8.72)","ar":"حَدَّثَنَا أَصْبَغُ، قَالَ أَخْبَرَنِي ابْنُ وَهْبٍ، عَنْ يُونُسَ، عَنِ ابْنِ شِهَابٍ، عَنْ عَلِيِّ بْنِ حُسَيْنٍ، عَنْ عَمْرِو بْنِ عُثْمَانَ، عَنْ أُسَامَةَ بْنِ زَيْدٍ ـ رضى الله عنهما ـ أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ، أَيْنَ تَنْزِلُ فِي دَارِكَ بِمَكَّةَ‏.‏ فَقَالَ ‏\"‏ وَهَلْ تَرَكَ عَقِيلٌ مِنْ رِبَاعٍ أَوْ دُورٍ ‏\"‏‏.‏ وَكَانَ عَقِيلٌ وَرِثَ أَبَا طَالِبٍ هُوَ وَطَالِبٌ وَلَمْ يَرِثْهُ جَعْفَرٌ وَلاَ عَلِيٌّ ـ رضى الله عنهما ـ شَيْئًا لأَنَّهُمَا كَانَا مُسْلِمَيْنِ، وَكَانَ عَقِيلٌ وَطَالِبٌ كَافِرَيْنِ، فَكَانَ عُمَرُ بْنُ الْخَطَّابِ ـ رضى الله عنه ـ يَقُولُ لاَ يَرِثُ الْمُؤْمِنُ الْكَافِرَ‏.‏ قَالَ ابْنُ شِهَابٍ وَكَانُوا يَتَأَوَّلُونَ قَوْلَ اللَّهِ تَعَالَى ‏{‏إِنَّ الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوْا وَنَصَرُوا أُولَئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ‏}‏ الآيَةَ‏.‏","v":[]}],"75":[{"c":"Sunan Abu Dawud","r":"Hadith 2927","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2927","x":"Narrated Umar ibn al-Khattab:\n\nSa'id said: Umar ibn al-Khattab said: Blood-money is meant for the clan of the slain, and she will not inherit from the blood-money of her husband. Ad-Dahhak ibn Sufyan said: The Messenger of Allah (ﷺ) wrote to me that I should give a share to the wife of Ashyam ad-Dubabi from the blood-money of her husband. So Umar withdrew his opinion. Ahmad ibn Salih said: AbdurRazzaq transmitted this tradition to us from Ma'mar, from az-Zuhri on the authority of Sa'id. In this version he said: The Prophet (ﷺ) made him governor over the bedouins.","ar":"حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ سَعِيدٍ، قَالَ كَانَ عُمَرُ بْنُ الْخَطَّابِ يَقُولُ الدِّيَةُ لِلْعَاقِلَةِ وَلاَ تَرِثُ الْمَرْأَةُ مِنْ دِيَةِ زَوْجِهَا شَيْئًا حَتَّى قَالَ لَهُ الضَّحَّاكُ بْنُ سُفْيَانَ كَتَبَ إِلَىَّ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ أُوَرِّثَ امْرَأَةَ أَشْيَمَ الضِّبَابِيِّ مِنْ دِيَةِ زَوْجِهَا ‏.‏ فَرَجَعَ عُمَرُ ‏.‏ قَالَ أَحْمَدُ بْنُ صَالِحٍ حَدَّثَنَا عَبْدُ الرَّزَّاقِ بِهَذَا الْحَدِيثِ عَنْ مَعْمَرٍ عَنِ الزُّهْرِيِّ عَنْ سَعِيدٍ وَقَالَ فِيهِ وَكَانَ النَّبِيُّ صلى الله عليه وسلم اسْتَعْمَلَهُ عَلَى الأَعْرَابِ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 2930","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-2930","x":"Narrated Abu Musa:\n\nI went along with two men to see the Prophet (ﷺ). One of them recited tashahhud and said: We have come to you so that you may employ us for your work. The other also said the same thing. He (the Prophet) replied: The most faithless of you in our eyes is the one who asked for it (responsible post). Abu Musa then apologized to the Prophet (ﷺ) and said: I did not know why they came to you. He did not employ them for anything until he died.","ar":"حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، حَدَّثَنَا خَالِدٌ، عَنْ إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ، عَنْ أَخِيهِ، عَنْ بِشْرِ بْنِ قُرَّةَ الْكَلْبِيِّ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى، قَالَ انْطَلَقْتُ مَعَ رَجُلَيْنِ إِلَى النَّبِيِّ صلى الله عليه وسلم فَتَشَهَّدَ أَحَدُهُمَا ثُمَّ قَالَ جِئْنَا لِتَسْتَعِينَ بِنَا عَلَى عَمَلِكَ ‏.‏ وَقَالَ الآخَرُ مِثْلَ قَوْلِ صَاحِبِهِ ‏.‏ فَقَالَ ‏\n\n\"‏ إِنَّ أَخْوَنَكُمْ عِنْدَنَا مَنْ طَلَبَهُ ‏\"\n\n‏ ‏.‏ فَاعْتَذَرَ أَبُو مُوسَى إِلَى النَّبِيِّ صلى الله عليه وسلم وَقَالَ لَمْ أَعْلَمْ لِمَا جَاءَا لَهُ ‏.‏ فَلَمْ يَسْتَعِنْ بِهِمَا عَلَى شَىْءٍ حَتَّى مَاتَ ‏.‏","v":[]}]};